def flags_to_groups(apps, schema_editor):
    """Convierte los antiguos booleanos can_* en grupos con permisos nativos."""
    from django.contrib.auth.management import create_permissions

    app_config = apps.get_app_config("core")
    app_config.models_module = True
    create_permissions(app_config, apps=apps, verbosity=0)
    app_config.models_module = None

    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    User = apps.get_model("core", "User")
    for codename, name in GROUPS.items():
        permission = Permission.objects.get(content_type__app_label="core", codename=codename)
        group, _ = Group.objects.get_or_create(name=name)
        group.permissions.add(permission)
        for user in User.objects.filter(**{f"can_{codename}": True}):
            user.groups.add(group)


